<?php
require_once __DIR__.'/../includes/marketplace.php';
$user=require_login('provider');
$stmt=db()->prepare("SELECT p.* FROM providers p WHERE p.user_id=? LIMIT 1");$stmt->bind_param('i',$user['id']);$stmt->execute();$provider=$stmt->get_result()->fetch_assoc();
if(!$provider){http_response_code(403);exit('Provider profile not found.');}
$stmt=db()->prepare("SELECT tr.*, (SELECT COUNT(*) FROM provider_bids b WHERE b.trip_request_id=tr.id AND b.provider_id=?) bid_count FROM trip_requests tr WHERE tr.status IN ('published','receiving_offers') AND (tr.expires_at IS NULL OR tr.expires_at>NOW()) ORDER BY tr.created_at DESC");$stmt->bind_param('i',$provider['id']);$stmt->execute();$requests=$stmt->get_result();
$page_title='Travel Requests';require __DIR__.'/../includes/header.php';
?><div class="container py-5"><div class="d-flex justify-content-between align-items-center mb-4"><div><h1 class="h3">Travel requests</h1><p class="text-secondary mb-0">Open RFQs available to verified providers.</p></div></div><?php if($provider['verification_status']==='pending'):?><div class="alert alert-warning">Your provider account is pending verification. You can review requests, but bidding should only be enabled after verification.</div><?php endif;?><div class="row g-3"><?php if($requests->num_rows===0):?><div class="col-12"><div class="card p-4 text-secondary">No open requests right now.</div></div><?php else: while($r=$requests->fetch_assoc()): $score=provider_match_score($r,$provider);?><div class="col-lg-6"><div class="card h-100 p-4"><div class="d-flex justify-content-between"><span class="badge text-bg-light"><?=e($r['request_number'])?></span><strong><?=$score?>% match</strong></div><h2 class="h5 mt-3 mb-1"><?=e($r['origin']?:'India')?> → <?=e($r['destination'])?></h2><div class="text-secondary mb-3"><?=e((string)$r['start_date'])?> → <?=e((string)$r['end_date'])?> · <?=e((string)$r['adults'])?> adults</div><p class="mb-2"><?=e($r['description']?:'No additional requirements.')?></p><div class="fw-semibold mb-3">Budget: ₹<?=number_format((float)$r['budget_min'])?> – ₹<?=number_format((float)$r['budget_max'])?></div><?php if($r['bid_count']):?><span class="text-secondary">Your offer has already been submitted.</span><?php elseif(in_array($provider['verification_status'],['verified','trusted','preferred'],true)):?><a class="btn btn-dark" href="/provider/bid-add.php?request_id=<?=$r['id']?>">Submit offer</a><?php else:?><span class="text-secondary">Verification required to bid.</span><?php endif;?></div></div><?php endwhile;endif;?></div></div><?php require __DIR__.'/../includes/footer.php'; ?>
